-- R48: counts the task lists show, kept on the task row so a list stops reading comments, checklist items, subtasks and
-- field values for every task (R47 on prod: about one row per task per lookup, four lookups per list). Triggers keep
-- them: each recounts from the source rows (no +1/-1 arithmetic), so every write path agrees, including imports and
-- data moves. field_count only says whether a task has field values (the list still reads the values it shows).
ALTER TABLE `tasks` ADD `comment_count` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE `tasks` ADD `checklist_total` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE `tasks` ADD `checklist_done` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE `tasks` ADD `subtask_total` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE `tasks` ADD `subtask_done` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE `tasks` ADD `field_count` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
-- Backfill: only tasks that have something to count are written (every other row keeps the default 0).
UPDATE `tasks` SET `comment_count` = (SELECT count(*) FROM `task_comments` WHERE `task_id` = `tasks`.`id` AND `deleted_at` IS NULL) WHERE `id` IN (SELECT `task_id` FROM `task_comments` WHERE `deleted_at` IS NULL);--> statement-breakpoint
UPDATE `tasks` SET `checklist_total` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = `tasks`.`id`), `checklist_done` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = `tasks`.`id` AND `done` = 1) WHERE `id` IN (SELECT `task_id` FROM `task_checklist_items`);--> statement-breakpoint
UPDATE `tasks` SET `subtask_total` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = `tasks`.`id` AND s.`deleted_at` IS NULL), `subtask_done` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = `tasks`.`id` AND s.`deleted_at` IS NULL AND s.`status` = 'done') WHERE `id` IN (SELECT `parent_id` FROM `tasks` WHERE `parent_id` IS NOT NULL AND `deleted_at` IS NULL);--> statement-breakpoint
UPDATE `tasks` SET `field_count` = (SELECT count(*) FROM `task_field_values` WHERE `task_id` = `tasks`.`id`) WHERE `id` IN (SELECT `task_id` FROM `task_field_values`);--> statement-breakpoint
CREATE TRIGGER `task_comments_count_ai` AFTER INSERT ON `task_comments` BEGIN UPDATE `tasks` SET `comment_count` = (SELECT count(*) FROM `task_comments` WHERE `task_id` = NEW.`task_id` AND `deleted_at` IS NULL) WHERE `id` = NEW.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_comments_count_ad` AFTER DELETE ON `task_comments` BEGIN UPDATE `tasks` SET `comment_count` = (SELECT count(*) FROM `task_comments` WHERE `task_id` = OLD.`task_id` AND `deleted_at` IS NULL) WHERE `id` = OLD.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_comments_count_au` AFTER UPDATE OF `deleted_at`, `task_id` ON `task_comments` BEGIN UPDATE `tasks` SET `comment_count` = (SELECT count(*) FROM `task_comments` WHERE `task_id` = NEW.`task_id` AND `deleted_at` IS NULL) WHERE `id` = NEW.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_comments_count_move` AFTER UPDATE OF `task_id` ON `task_comments` WHEN OLD.`task_id` IS NOT NEW.`task_id` BEGIN UPDATE `tasks` SET `comment_count` = (SELECT count(*) FROM `task_comments` WHERE `task_id` = OLD.`task_id` AND `deleted_at` IS NULL) WHERE `id` = OLD.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_checklist_count_ai` AFTER INSERT ON `task_checklist_items` BEGIN UPDATE `tasks` SET `checklist_total` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = NEW.`task_id`), `checklist_done` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = NEW.`task_id` AND `done` = 1) WHERE `id` = NEW.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_checklist_count_ad` AFTER DELETE ON `task_checklist_items` BEGIN UPDATE `tasks` SET `checklist_total` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = OLD.`task_id`), `checklist_done` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = OLD.`task_id` AND `done` = 1) WHERE `id` = OLD.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_checklist_count_au` AFTER UPDATE OF `done`, `task_id` ON `task_checklist_items` BEGIN UPDATE `tasks` SET `checklist_total` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = NEW.`task_id`), `checklist_done` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = NEW.`task_id` AND `done` = 1) WHERE `id` = NEW.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_checklist_count_move` AFTER UPDATE OF `task_id` ON `task_checklist_items` WHEN OLD.`task_id` IS NOT NEW.`task_id` BEGIN UPDATE `tasks` SET `checklist_total` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = OLD.`task_id`), `checklist_done` = (SELECT count(*) FROM `task_checklist_items` WHERE `task_id` = OLD.`task_id` AND `done` = 1) WHERE `id` = OLD.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_fields_count_ai` AFTER INSERT ON `task_field_values` BEGIN UPDATE `tasks` SET `field_count` = (SELECT count(*) FROM `task_field_values` WHERE `task_id` = NEW.`task_id`) WHERE `id` = NEW.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `task_fields_count_ad` AFTER DELETE ON `task_field_values` BEGIN UPDATE `tasks` SET `field_count` = (SELECT count(*) FROM `task_field_values` WHERE `task_id` = OLD.`task_id`) WHERE `id` = OLD.`task_id`; END;--> statement-breakpoint
CREATE TRIGGER `tasks_subtask_count_ai` AFTER INSERT ON `tasks` WHEN NEW.`parent_id` IS NOT NULL BEGIN UPDATE `tasks` SET `subtask_total` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = NEW.`parent_id` AND s.`deleted_at` IS NULL), `subtask_done` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = NEW.`parent_id` AND s.`deleted_at` IS NULL AND s.`status` = 'done') WHERE `id` = NEW.`parent_id`; END;--> statement-breakpoint
CREATE TRIGGER `tasks_subtask_count_ad` AFTER DELETE ON `tasks` WHEN OLD.`parent_id` IS NOT NULL BEGIN UPDATE `tasks` SET `subtask_total` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = OLD.`parent_id` AND s.`deleted_at` IS NULL), `subtask_done` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = OLD.`parent_id` AND s.`deleted_at` IS NULL AND s.`status` = 'done') WHERE `id` = OLD.`parent_id`; END;--> statement-breakpoint
CREATE TRIGGER `tasks_subtask_count_au` AFTER UPDATE OF `parent_id`, `status`, `deleted_at` ON `tasks` WHEN NEW.`parent_id` IS NOT NULL AND (NEW.`parent_id` IS NOT OLD.`parent_id` OR NEW.`status` IS NOT OLD.`status` OR NEW.`deleted_at` IS NOT OLD.`deleted_at`) BEGIN UPDATE `tasks` SET `subtask_total` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = NEW.`parent_id` AND s.`deleted_at` IS NULL), `subtask_done` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = NEW.`parent_id` AND s.`deleted_at` IS NULL AND s.`status` = 'done') WHERE `id` = NEW.`parent_id`; END;--> statement-breakpoint
CREATE TRIGGER `tasks_subtask_count_move` AFTER UPDATE OF `parent_id` ON `tasks` WHEN OLD.`parent_id` IS NOT NULL AND OLD.`parent_id` IS NOT NEW.`parent_id` BEGIN UPDATE `tasks` SET `subtask_total` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = OLD.`parent_id` AND s.`deleted_at` IS NULL), `subtask_done` = (SELECT count(*) FROM `tasks` s WHERE s.`parent_id` = OLD.`parent_id` AND s.`deleted_at` IS NULL AND s.`status` = 'done') WHERE `id` = OLD.`parent_id`; END;
